contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call with payment amount and observed preimage parts (timestamp/difficulty cannot be read),
    // so we instead call play and observe pot and contract balance to infer whether payout happened.
    // We require the caller has enough balance to send 'amount'.
    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance for test");
        // precondition: ticket must match contract's TICKET_AMOUNT constant (10), but we don't access it directly.
        // We rely on caller supplying correct amount.

        // Capture contract balance before play
        uint balBefore = address(c).balance;

        // call play which may reset pot and transfer
        c.play{value: amount}();

        // Observe contract balance and pot
        uint balAfter = address(c).balance;
        uint potAfter = c.pot();

        // If the play triggered a payout, the contract's pot is reset to 0 and the contract balance decreased by (amount - FEE_AMOUNT)
        // We assert a distinguishing property: whenever potAfter == 0 then the contract balance did not increase (balAfter <= balBefore + 0).
        // This will hold for original which pays out when random==0, but will be violated by the mutant that pays out on the opposite random branch
        assert(!(potAfter == 0) || balAfter <= balBefore);
    }

    // Allow funding this test contract for the require(address(this).balance >= amount) check
    receive() external payable {}
}

contract InvMutTest {
    C c;
    uint public __snap;
    bool public __obsd;

    constructor(C _c) { c = _c; }

    // we take the ticket payment as a parameter
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // require correct ticket size to enter play
        require(amount > 0);

        // reset observation flags
        __obsd = false;
        __snap = 0;

        // call play sending Ether; the difference appears during the external call
        c.play{value: amount}();

        // After the external call, the observed mid-call pot snapshot must have been
        // equal to the payout amount sent to the player (pot - FEE_AMOUNT) when the
        // payout branch executed. On the correct contract, that happens iff random==0.
        // We cannot read random, but we can assert that any observed snapshot is equal
        // to address(this).balance (the Ether the test contract received) + (amount - 1)
        // only when a payout occurred. Here we state a general relation: if we observed
        // a mid-call snapshot, it must equal the Ether we received plus the fee kept by bank.

        // Note: assert is over observable values: __obsd, __snap, and address(this).balance.
        // On the original contract, when a payout happens, __snap == address(this).balance + 1.
        assert(!__obsd || __snap == address(this).balance + 1);
    }

    // receive() is invoked during c.play() when the contract transfers to msg.sender (this)
    receive() external payable {
        if (!__obsd) {
            __obsd = true;
            // snapshot the pot MID-call using the public getter
            __snap = c.pot();
        }
    }
}

