contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the caller address and an arbitrary uint nonce to influence block.timestamp/difficulty
    function testFuzz_property(address caller, uint256 junk) public {
        // Keep caller as a usable address
        vm.assume(caller != address(0));

        // We need to make a deterministic attempt to cause the reference's random to be 0.
        // We cannot directly set keccak inputs, but we can call play repeatedly until the computed random is 0.
        // To stay within admissible domain: caller must send exactly TICKET_AMOUNT (10).
        uint256 TICKET = 10;
        vm.deal(caller, 1 ether);

        // Try several times (fuzzer-supplied junk changes nothing here but counts as a param)
        // We will call from the fuzzed caller up to 8 times; this keeps domain wide.
        bool observedReset = false;
        for (uint i = 0; i < 8; i++) {
            vm.prank(caller);
            // call play with exact ticket amount
            (bool ok, ) = address(c).call{value: TICKET}(abi.encodeWithSignature("play()"));
            // If call succeeded, check pot; when payout occurred in reference (random==0) pot should be zero.
            // We observe pot via public getter c.pot(). If at any successful call pot==0 afterwards, note it.
            if (ok) {
                if (c.pot() == 0) {
                    observedReset = true;
                    break;
                }
            }
            // advance block to change timestamp/difficulty entropy
            vm.warp(block.timestamp + 1);
            vm.roll(block.number + 1);
        }

        // The general property: there exists a call where the reference resets pot to 0 after play() completes.
        // For the correct contract, given varying block.timestamp/difficulty across attempts, we expect at least
        // one execution to hit random==0 and thus observe pot==0 after completion. The mutant flips the condition
        // and will fail to reset pot for those inputs, so the test will fail on the mutant for some fuzzed runs.
        assertTrue(observedReset);
    }
}

